reports=[]
period="IF @Desde IS NULL OR @Hasta IS NULL OR @Desde>@Hasta OR @Hasta='99991231' THROW 51300,'Periodo de fechas invalido.',1;"
cut="SET @FechaCorte=COALESCE(@FechaCorte,CONVERT(date,dbo.fn_AhoraGuatemala())); IF @FechaCorte='99991231' THROW 51301,'Fecha de corte fuera de rango.',1;"
nombre="CONCAT(p.PrimerNombre,N' ',p.SegundoNombre,N' ',p.PrimerApellido,N' ',p.SegundoApellido)"
def report(n,name,params,body,why):
    full=f'Reporte{n:02d}_{name}'
    reports.append(dict(numero=n,procedimiento='api.'+full,utilidad=why))
    proc(full,params,body)

report(1,'CreditosEmitidos','@Desde date,@Hasta date',period+'''
 SELECT c.NumeroCredito,c.FechaAprobacion,c.CodigoDeudor,c.CodigoVendedor,c.PrecioContado,c.Enganche,c.MontoFinanciado,c.Plazo,c.TotalIntereses,c.TotalNetoRecaudable,c.Estado,c.FechaAnulacion
 FROM dbo.vw_CreditoResumen c WHERE c.FechaAprobacion>=@Desde AND c.FechaAprobacion<DATEADD(day,1,CONVERT(datetime2,@Hasta)) ORDER BY c.FechaAprobacion,c.NumeroCredito;
 SELECT COUNT(*) CreditosEmitidos,SUM(MontoFinanciado) CapitalColocadoBruto FROM dbo.vw_CreditoResumen WHERE FechaAprobacion>=@Desde AND FechaAprobacion<DATEADD(day,1,CONVERT(datetime2,@Hasta));
''','Mide colocacion bruta por periodo; muestra anulaciones por separado, sin ocultar que el credito fue emitido.')
report(2,'CarteraMora','@FechaCorte date=NULL,@DiasMinimos int=1',cut+'''
 IF @DiasMinimos<1 OR @DiasMinimos IS NULL THROW 51302,'Los dias minimos deben ser al menos uno.',1;
 SELECT NumeroCredito,CodigoDeudor,MIN(FechaVencimiento) PrimerVencimientoPendiente,MAX(DATEDIFF(day,FechaVencimiento,@FechaCorte)) DiasMora,SUM(SaldoPendiente) TotalVencidoPendiente,COUNT(*) CuotasVencidas
 FROM dbo.fn_Saldos(@FechaCorte) WHERE FechaVencimiento<@FechaCorte AND SaldoPendiente>0 GROUP BY NumeroCredito,CodigoDeudor HAVING MAX(DATEDIFF(day,FechaVencimiento,@FechaCorte))>=@DiasMinimos ORDER BY DiasMora DESC,TotalVencidoPendiente DESC;
''','Determina creditos con cuotas vencidas pendientes al corte, incorporando abonos y anulaciones historicas.')
cash='''WITH Movimiento AS(
 SELECT CodigoTipoPago,Monto,Capital,Interes,ManejoCuenta,SeguroAuto,SeguroVida,1 Recibido FROM dbo.vw_PagoDesglosado WHERE FechaPago>=@Desde AND FechaPago<DATEADD(day,1,CONVERT(datetime2,@Hasta))
 UNION ALL
 SELECT CodigoTipoPago,-Monto,-Capital,-Interes,-ManejoCuenta,-SeguroAuto,-SeguroVida,0 FROM dbo.vw_PagoDesglosado WHERE FechaAnulacion>=@Desde AND FechaAnulacion<DATEADD(day,1,CONVERT(datetime2,@Hasta)))
'''
report(3,'PagosPorMedio','@Desde date,@Hasta date',period+cash+'''
 SELECT t.CodigoTipoPago,t.Descripcion,SUM(CASE WHEN m.Recibido=1 THEN 1 ELSE 0 END) PagosRecibidos,SUM(CASE WHEN m.Recibido=1 THEN m.Monto ELSE 0 END) ImporteRecibido,SUM(CASE WHEN m.Recibido=0 THEN -m.Monto ELSE 0 END) ImporteAnulado,SUM(m.Monto) MovimientoNeto
 FROM Movimiento m JOIN dbo.TipoPago t ON t.CodigoTipoPago=m.CodigoTipoPago GROUP BY t.CodigoTipoPago,t.Descripcion ORDER BY PagosRecibidos DESC;
''','Compara uso de los cinco medios de pago y distingue ingresos y reversiones del periodo.')
report(4,'VentasVendedor','@Desde date,@Hasta date',period+f'''
 SELECT v.CodigoVendedor,v.CodigoEmpleado,{nombre} Vendedor,COUNT(*) Creditos,SUM(c.MontoFinanciado) CapitalColocado
 FROM dbo.vw_CreditoResumen c JOIN dbo.Vendedor v ON v.CodigoVendedor=c.CodigoVendedor JOIN dbo.Persona p ON p.CodigoPersona=v.CodigoPersona
 WHERE c.FechaAprobacion>=@Desde AND c.FechaAprobacion<DATEADD(day,1,CONVERT(datetime2,@Hasta)) AND(c.FechaAnulacion IS NULL OR c.FechaAnulacion>=DATEADD(day,1,CONVERT(datetime2,@Hasta)))
 GROUP BY v.CodigoVendedor,v.CodigoEmpleado,p.PrimerNombre,p.SegundoNombre,p.PrimerApellido,p.SegundoApellido ORDER BY CapitalColocado DESC,Creditos DESC;
''','Clasifica vendedores por capital colocado en creditos no anulados al cierre del periodo.')
report(5,'Cumpleaneros','@Mes int,@Anio int',f'''
 IF @Mes NOT BETWEEN 1 AND 12 OR @Anio NOT BETWEEN 1900 AND 9998 OR @Mes IS NULL OR @Anio IS NULL THROW 51303,'Mes o anio invalido.',1;
 SELECT d.CodigoDeudor,{nombre} Cliente,p.FechaNacimiento,p.CorreoElectronico,@Anio-YEAR(p.FechaNacimiento) EdadQueCumple,
 CONCAT(N'Estimado/a ',{nombre},N': en MAGIS-AUTO le deseamos un feliz cumpleanos. Que este nuevo anio de vida le traiga salud y buenos momentos. Gracias por su confianza. Atentamente, equipo MAGIS-AUTO.') CartaFelicitacion
 FROM dbo.Deudor d JOIN dbo.Persona p ON p.CodigoPersona=d.CodigoPersona WHERE MONTH(p.FechaNacimiento)=@Mes AND YEAR(p.FechaNacimiento)<=@Anio ORDER BY DAY(p.FechaNacimiento),d.CodigoDeudor;
''','Lista clientes cumpleaneros y genera el texto individual de su carta, sin enviar correos automaticamente.')
report(6,'EstadoCuenta','@CodigoDeudor int,@FechaCorte date=NULL',cut+'''
 IF NOT EXISTS(SELECT 1 FROM dbo.Deudor WHERE CodigoDeudor=@CodigoDeudor) THROW 51304,'Cliente inexistente.',1;
 SELECT NumeroCredito,SUM(Total) TotalPlan,SUM(Total-SaldoPendiente) PagadoAlCorte,SUM(SaldoPendiente) SaldoTotal,SUM(CapitalPendiente) SaldoCapital,SUM(CASE WHEN FechaVencimiento<@FechaCorte THEN SaldoPendiente ELSE 0 END) VencidoPendiente FROM dbo.fn_Saldos(@FechaCorte) WHERE CodigoDeudor=@CodigoDeudor GROUP BY NumeroCredito;
 SELECT * FROM dbo.fn_Saldos(@FechaCorte) WHERE CodigoDeudor=@CodigoDeudor ORDER BY NumeroCredito,Cuota;
 SELECT p.*,CASE WHEN p.FechaAnulacion IS NULL OR p.FechaAnulacion>=DATEADD(day,1,CONVERT(datetime2,@FechaCorte)) THEN 1 ELSE 0 END VigenteAlCorte FROM dbo.vw_PagoDesglosado p JOIN dbo.vw_CreditoResumen c ON c.NumeroCredito=p.NumeroCredito WHERE c.CodigoDeudor=@CodigoDeudor AND p.FechaPago<DATEADD(day,1,CONVERT(datetime2,@FechaCorte)) ORDER BY p.FechaPago,p.CodigoPago;
''','Entrega resumen por credito, cuotas y movimientos del cliente hasta una fecha.')
report(7,'PlanPagos','@NumeroCredito varchar(20),@FechaCorte date=NULL',cut+'''
 IF NOT EXISTS(SELECT 1 FROM dbo.vw_CreditoResumen WHERE NumeroCredito=@NumeroCredito) THROW 51305,'Credito inexistente.',1;
 SELECT c.NumeroCredito,c.Estado,c.FechaAprobacion,c.Plazo,c.PrecioContado,c.Enganche,c.MontoFinanciado,c.TasaAnual,c.TotalIntereses,c.TotalNetoRecaudable FROM dbo.vw_CreditoResumen c WHERE NumeroCredito=@NumeroCredito;
 SELECT q.*,s.SaldoPendiente,s.CapitalPendiente FROM dbo.vw_CuotaDesglosada q LEFT JOIN dbo.fn_Saldos(@FechaCorte)s ON s.NumeroCredito=q.NumeroCredito AND s.Cuota=q.Cuota WHERE q.NumeroCredito=@NumeroCredito ORDER BY q.Cuota;
''','Muestra todas las cuotas del contrato y su desglose; el saldo al corte es nulo si el contrato no estaba vigente al corte.')
report(8,'Comisiones','@Desde date,@Hasta date',period+f'''
 WITH Mov AS(
 SELECT p.NumeroCredito,p.Comision Generada,CONVERT(decimal(18,2),0) Revertida FROM dbo.vw_PagoDesglosado p WHERE p.FechaPago>=@Desde AND p.FechaPago<DATEADD(day,1,CONVERT(datetime2,@Hasta))
 UNION ALL SELECT p.NumeroCredito,0,p.Comision FROM dbo.vw_PagoDesglosado p WHERE p.FechaAnulacion>=@Desde AND p.FechaAnulacion<DATEADD(day,1,CONVERT(datetime2,@Hasta)))
 SELECT v.CodigoVendedor,{nombre} Vendedor,SUM(m.Generada) ComisionGenerada,SUM(m.Revertida) ComisionRevertida,SUM(m.Generada-m.Revertida) ComisionNeta
 FROM Mov m JOIN dbo.vw_CreditoResumen c ON c.NumeroCredito=m.NumeroCredito JOIN dbo.Vendedor v ON v.CodigoVendedor=c.CodigoVendedor JOIN dbo.Persona p ON p.CodigoPersona=v.CodigoPersona GROUP BY v.CodigoVendedor,p.PrimerNombre,p.SegundoNombre,p.PrimerApellido,p.SegundoApellido ORDER BY ComisionNeta DESC;
''','Audita la comision generada y revertida por vendedor; no afirma que haya sido desembolsada al vendedor.')
report(9,'CapitalPendiente','@FechaCorte date=NULL',cut+'''SELECT NumeroCredito,CodigoDeudor,SUM(Capital) CapitalFinanciado,SUM(Capital-CapitalPendiente) CapitalRecuperado,SUM(CapitalPendiente) CapitalPendiente FROM dbo.fn_Saldos(@FechaCorte) GROUP BY NumeroCredito,CodigoDeudor ORDER BY CapitalPendiente DESC;''','Mide cuanto capital se ha recuperado y cuanto falta recuperar por credito.')
report(10,'Intereses','@FechaCorte date=NULL',cut+'''SELECT NumeroCredito,SUM(Interes) InteresesDelContrato,SUM(Interes-InteresPendiente) InteresesCobrados,SUM(InteresPendiente) InteresesPendientes FROM dbo.fn_Saldos(@FechaCorte) GROUP BY NumeroCredito ORDER BY NumeroCredito;''','Compara los intereses proyectados del plan con los cobrados; no confunde proyeccion con devengo contable.')
report(11,'ProximosVencimientos','@FechaCorte date=NULL,@Dias int=30',cut+'''IF @Dias NOT BETWEEN 1 AND 365 OR @Dias IS NULL THROW 51306,'Horizonte permitido: 1 a 365 dias.',1; SELECT * FROM dbo.fn_Saldos(@FechaCorte) WHERE SaldoPendiente>0 AND FechaVencimiento>=@FechaCorte AND FechaVencimiento<=DATEADD(day,@Dias,@FechaCorte) ORDER BY FechaVencimiento,NumeroCredito,Cuota;''','Prepara la cobranza de cuotas pendientes que vencen dentro del horizonte indicado.')
report(12,'AbonosParciales','@FechaCorte date=NULL',cut+'''SELECT NumeroCredito,Cuota,FechaVencimiento,Total,Total-SaldoPendiente Pagado,SaldoPendiente FROM dbo.fn_Saldos(@FechaCorte) WHERE SaldoPendiente>0 AND SaldoPendiente<Total ORDER BY FechaVencimiento,NumeroCredito;''','Localiza cuotas que recibieron abonos pero todavia no estan liquidadas.')
report(13,'CreditosMarcaLinea','@Desde date,@Hasta date',period+'''SELECT m.CodigoMarca,m.Descripcion Marca,l.CodigoLinea,l.Descripcion Linea,COUNT(*) Creditos,SUM(c.MontoFinanciado) CapitalFinanciado FROM dbo.vw_CreditoResumen c JOIN dbo.Garantia g ON g.CodigoGarantia=c.CodigoGarantia JOIN dbo.Marca m ON m.CodigoMarca=g.CodigoMarca JOIN dbo.Linea l ON l.CodigoMarca=g.CodigoMarca AND l.CodigoLinea=g.CodigoLinea WHERE c.FechaAprobacion>=@Desde AND c.FechaAprobacion<DATEADD(day,1,CONVERT(datetime2,@Hasta)) AND(c.FechaAnulacion IS NULL OR c.FechaAnulacion>=DATEADD(day,1,CONVERT(datetime2,@Hasta))) GROUP BY m.CodigoMarca,m.Descripcion,l.CodigoLinea,l.Descripcion ORDER BY CapitalFinanciado DESC;''','Compara la colocacion por marca y linea de vehiculo, excluyendo anulaciones al cierre.')
report(14,'CarteraAgenciaRegion','@FechaCorte date=NULL',cut+'''SELECT a.CodigoAgencia,a.Nombre,a.Region,COUNT(DISTINCT s.NumeroCredito) CreditosConSaldo,SUM(s.CapitalPendiente) CapitalPendiente,SUM(s.SaldoPendiente) SaldoContractual,SUM(CASE WHEN s.FechaVencimiento<@FechaCorte THEN s.SaldoPendiente ELSE 0 END) Vencido FROM dbo.fn_Saldos(@FechaCorte)s JOIN dbo.Agencia a ON a.CodigoAgencia=s.CodigoAgencia WHERE s.SaldoPendiente>0 GROUP BY a.CodigoAgencia,a.Nombre,a.Region ORDER BY CapitalPendiente DESC;''','Compara cartera y mora por agencia y region; cuenta cada credito una sola vez.')
report(15,'MoraRangos','@FechaCorte date=NULL',cut+'''WITH Mora AS(SELECT NumeroCredito,MAX(DATEDIFF(day,FechaVencimiento,@FechaCorte)) Dias,SUM(SaldoPendiente) Vencido FROM dbo.fn_Saldos(@FechaCorte) WHERE FechaVencimiento<@FechaCorte AND SaldoPendiente>0 GROUP BY NumeroCredito),R AS(SELECT *,CASE WHEN Dias<=30 THEN '01-30' WHEN Dias<=60 THEN '31-60' WHEN Dias<=90 THEN '61-90' ELSE '91 o mas' END Rango FROM Mora) SELECT Rango,COUNT(*) Creditos,SUM(Vencido) VencidoPendiente FROM R GROUP BY Rango ORDER BY MIN(Dias);''','Clasifica cada credito por su cuota pendiente mas antigua y suma su deuda vencida.')
valuation='''OUTER APPLY(SELECT TOP(1) d.FechaValoracion,d.ValorDepreciado FROM dbo.vw_DepreciacionCalculada d WHERE d.CodigoGarantia=c.CodigoGarantia AND d.FechaValoracion<=@FechaCorte ORDER BY d.FechaValoracion DESC,d.CodigoDepreciacion DESC)v'''
report(16,'GarantiaContraCapital','@FechaCorte date=NULL',cut+f'''WITH S AS(SELECT NumeroCredito,SUM(CapitalPendiente) CapitalPendiente FROM dbo.fn_Saldos(@FechaCorte) GROUP BY NumeroCredito) SELECT c.NumeroCredito,g.VIN,c.PrecioContado,v.FechaValoracion,v.ValorDepreciado,s.CapitalPendiente,v.ValorDepreciado-s.CapitalPendiente MargenGarantia,CASE WHEN v.ValorDepreciado<s.CapitalPendiente THEN 1 ELSE 0 END GarantiaInsuficiente FROM S s JOIN dbo.vw_CreditoResumen c ON c.NumeroCredito=s.NumeroCredito JOIN dbo.Garantia g ON g.CodigoGarantia=c.CodigoGarantia {valuation} ORDER BY MargenGarantia;''','Compara la ultima valoracion conocida al corte con el capital pendiente, sin modificar la deuda.')
report(17,'DepreciacionCostoFinanciamiento','@FechaCorte date=NULL',cut+f'''SELECT c.NumeroCredito,c.PrecioContado,c.Enganche,c.MontoFinanciado,c.TotalIntereses,c.TotalNetoRecaudable,c.TotalNetoRecaudable-c.MontoFinanciado CostoFinanciamientoYCargos,c.Enganche+c.TotalNetoRecaudable DesembolsoTotalCliente,v.FechaValoracion,v.ValorDepreciado,c.PrecioContado-v.ValorDepreciado PerdidaValorEstimada FROM dbo.vw_CreditoResumen c {valuation} WHERE c.FechaAprobacion<DATEADD(day,1,CONVERT(datetime2,@FechaCorte)) AND(c.FechaAnulacion IS NULL OR c.FechaAnulacion>=DATEADD(day,1,CONVERT(datetime2,@FechaCorte))) ORDER BY c.NumeroCredito;''','Relaciona precio, depreciacion y desembolso contractual del cliente. Los cargos no se presentan como ganancia neta.')
report(18,'CreditosFiador','@FechaCorte date=NULL',cut+f'''WITH S AS(SELECT NumeroCredito,SUM(CapitalPendiente) CapitalPendiente,SUM(SaldoPendiente) SaldoTotal FROM dbo.fn_Saldos(@FechaCorte) GROUP BY NumeroCredito) SELECT f.CodigoFiador,{nombre} Fiador,c.NumeroCredito,s.CapitalPendiente,s.SaldoTotal,COUNT(*) OVER(PARTITION BY f.CodigoFiador) CreditosRespaldados FROM dbo.CreditoFiador cf JOIN dbo.Fiador f ON f.CodigoFiador=cf.CodigoFiador JOIN dbo.Persona p ON p.CodigoPersona=f.CodigoPersona JOIN dbo.vw_CreditoResumen c ON c.NumeroCredito=cf.NumeroCredito JOIN S s ON s.NumeroCredito=c.NumeroCredito WHERE s.SaldoTotal>0 ORDER BY f.CodigoFiador,c.NumeroCredito;''','Identifica la exposicion de cada fiador. Un mismo credito puede aparecer con distintos fiadores y no debe sumarse como cartera global.')
report(19,'RecaudacionComponentes','@Desde date,@Hasta date',period+cash+'''SELECT COALESCE(SUM(Capital),0) CapitalNeto,COALESCE(SUM(Interes),0) InteresesNetos,COALESCE(SUM(ManejoCuenta),0) ManejoNeto,COALESCE(SUM(SeguroAuto),0) SeguroAutoNeto,COALESCE(SUM(SeguroVida),0) SeguroVidaNeto,COALESCE(SUM(Monto),0) MovimientoNeto FROM Movimiento;''','Separa los componentes cobrados y resta las anulaciones ocurridas durante el periodo.')
report(20,'PagosAnulados','@Desde date,@Hasta date',period+'''SELECT CodigoPago,Comprobante,NumeroCredito,Cuota,FechaPago,FechaAnulacion,Monto,Comision ComisionRevertida,MotivoAnulacion,AnuladoPor FROM dbo.vw_PagoDesglosado WHERE FechaAnulacion>=@Desde AND FechaAnulacion<DATEADD(day,1,CONVERT(datetime2,@Hasta)) ORDER BY FechaAnulacion,CodigoPago;''','Permite auditar las anulaciones, sus responsables y los importes y comisiones revertidos.')
(OUT/'reportes.json').write_text(json.dumps(reports,ensure_ascii=False,indent=2),encoding='utf-8')
